insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('tao', '逃！', '乐正绫', 'VO大自然（词/曲）· OQQ（调教·ACE版）/ VO大自然（调教·V3版）· ヘロイン（动画）', '2024-08-22', 'https://www.bilibili.com/video/BV1tz421i7S7', NULL, '["传说曲","双版本传说","❗️系列第一作"]'::jsonb, '「❗️系列」第一作。B站简介只有一句「少女离家出走中..」：少女困在只剩争吵与说教的家里，「爱着我，却又伤害我」，她选择逃——「我只想逃，逃离这痛苦的喧嚣；我只想跑，就算盲目就算跌倒」。同日投稿 ACE 版（BV1TS421d7dZ，395.03万，调教 OQQ）与 V3 版（本条，485.79万），两个版本双双达成传说曲；V3 版四百万用时429日16时54分。2025-04-12 登上乐正绫十周年「向绫光」生日会。', 'tanhao', '{"plays":486,"asOf":"2026-10-29","note":"快照 486万（V3版 view API=4857911；ACE版另有395.03万，两版合计约881万）"}'::jsonb, '[{"caption":"「爱着我，却又伤害我」——所谓的爱，从来没有问过她内心的感受，只剩悲哀与沉默。（据歌词）"},{"caption":"「要听话，别太多想法，辛苦把你养大」——受够了争吵与无意义的说教，这里是否也是她的家？（据歌词）"},{"caption":"我自己的路自己走就好，再也不需要谁指手画脚；下地狱或上天堂，有什么紧要。（据歌词）"},{"caption":"我只想逃，逃离这痛苦的喧嚣；我只想跑，就算盲目、就算跌倒。（据歌词）"},{"caption":"用沉默代替回答——「都是我的错，因为你们爱着我」「因为你们，生下我」。（据歌词）"},{"caption":"少女离家出走中..（B站简介原句）"}]'::jsonb, '[{"label":"投稿B站（ACE版 BV1TS421d7dZ 18:05 / V3版 BV1tz421i7S7 18:10）· ❗️系列第一作","date":"2024-08-22"},{"label":"ACE版 100万播放 · 传说曲（用时15日03时53分）","date":"2024-09-06"},{"label":"V3版 100万播放 · 传说曲（用时30日15时44分）","date":"2024-09-22"},{"label":"ACE版 300万播放","date":"2025-06-25"},{"label":"V3版 400万播放（用时429日16时54分）","date":"2025-10-26"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('juan', '卷！', '乐正绫', 'VO大自然（词/曲/混音）· OQQ（调教）· ヘロイン / 洛因（曲绘/PV）', '2025-02-28', 'https://www.bilibili.com/video/BV1Sw9PYiEqG', NULL, '["传说曲","《逃！》续作"]'::jsonb, '「❗️系列」第二作，《逃！》续作。写「内卷」的社会议题曲，引「关山难越，谁悲失路之人？」作题眼：为了不输在起跑线就提前起跑线，蹉跎十六年递出简历才发现「卷不过的是别人的起点」；所有人怕被同龄人抛下而拼命往上爬，庙堂太深太远，渺小的呼声不被听见。传说曲，百万用时仅22日05时02分，周刊第657期以180万分登顶；2025-10-02 突破两百万。', 'tanhao', '{"plays":291,"asOf":"2026-10-29","note":"快照 291万（B站 view API stat.view=2905126，2026-10-29）"}'::jsonb, '[{"caption":"为了不输在起跑线，必须将起跑线提前——尝到了抢跑酿的甜，就把荒谬奉为圭臬。（据歌词）"},{"caption":"如此蹉跎了十六年，递出简历任人挑拣；碰壁后才发现：卷不过的，是别人的起点。（据歌词）"},{"caption":"小时候被教导要听话，什么爱好统统抹杀；长大又被工作碾压，劳动也开始异化。（据歌词）"},{"caption":"所有人都害怕被同龄人抛下，于是所有人都拼命往上爬——没有天赋没有背景的人生，从一开始就注定被放弃吗？（据歌词）"},{"caption":"关山难越，更多的关山难越；拼命向前，连自身存在都抛却。（据歌词）"},{"caption":"庙堂太深、太远，渺小的呼声不被听见——在这片穷途末路的旷野，「卷！」（据歌词）"}]'::jsonb, '[{"label":"投稿B站（BV1Sw9PYiEqG）· 《逃！》续作","date":"2025-02-28"},{"label":"100万播放 · 传说曲（用时22日05时02分）","date":"2025-03-22"},{"label":"200万播放","date":"2025-10-02"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('pao', '跑！', '乐正绫', 'Mara_然（词/曲/混音）· 洛因（动画）', '2025-09-05', 'https://www.bilibili.com/video/BV1oWabz3EGQ', NULL, '["传说曲","反校园霸凌","《卷！》续作"]'::jsonb, '「❗️系列」第三作，《卷！》续作，反校园霸凌题材，简介一句「揍飞你们！！」。面对趁睡觉骚扰、背后造谣的霸凌者，主角忍无可忍选择反击——「给我跑，你要往哪儿跑，你的身后是死路一条」。⚠ 作者特别说明：现实中这样的行为并不提倡，请勿模仿。传说曲，百万仅用时8日19时58分，为系列最快；2026-03-24 突破四百万。', 'tanhao', '{"plays":486,"asOf":"2026-10-29","note":"快照 486万（B站 view API stat.view=4862542，2026-10-29）"}'::jsonb, '[{"caption":"告诫的话说了三遍，她把宽容当成弱点——趁睡觉偷偷骚扰、背后造谣，真当她不知道。（据歌词）"},{"caption":"非要等到她拔刀，才明白大事已经不妙。（据歌词）"},{"caption":"「给我跑，你要往哪儿跑——你的身后是死路一条」「放你跑，我帮你读秒」。（据歌词）"},{"caption":"满脑子的黄色废料，捡一个烂梗当成宝，一张嘴用来胡说八道。（据歌词）"},{"caption":"「什么叫我在欺负你？难道不是你先来挑衅。我只是想和你玩一个游戏。」（据歌词）"},{"caption":"嗷呜！（结尾一嗓子。⚠ 官方说明：现实中的反击行为不提倡，请勿模仿）"}]'::jsonb, '[{"label":"投稿B站（BV1oWabz3EGQ）· 《卷！》续作 · 反校园霸凌","date":"2025-09-05"},{"label":"100万播放 · 传说曲（用时8日19时58分，系列最快）","date":"2025-09-14"},{"label":"200万播放","date":"2025-10-12"},{"label":"300万播放","date":"2026-02-01"},{"label":"400万播放","date":"2026-03-24"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('xin', '心', '乐正绫', 'Mara_然（词/曲）· 鬼面P（调教）· 洛因（动画）', '2026-03-28', 'https://www.bilibili.com/video/BV1VmX5BwE2b', NULL, '["传说曲","ACE传说曲","《跑！》续作"]'::jsonb, '「❗️系列」第四作，《跑！》续作，标题不带感叹号。作者 Mara_然 因《跑！》的词作遭受网暴，本曲是那段经历后的心声：在深渊里被无数噪音侵袭，无数稚嫩的面孔举着「正义」的屠刀批判、解剖她——「请你来听听我的心，如何证明我的真心」。ACE传说曲，传说用时20日01时38分，截至2026-10-29 已有171.21万播放。', 'tanhao', '{"plays":171,"asOf":"2026-10-29","note":"快照 171万（B站 view API stat.view=1712075，2026-10-29）"}'::jsonb, '[{"caption":"在黑暗里、在深渊里，无数噪音向她侵袭；天空窒息、鸟儿死去，一颗心被沉入海底。（据歌词）"},{"caption":"她看见无数稚嫩的面孔举起「正义」的屠刀指向她：批判她、解剖她，嘲笑着她的死相丑陋。（据歌词）"},{"caption":"于是她一遍又一遍地质问自己，在深渊之中寻求着回应。（据歌词）"},{"caption":"「请你来听，请你来听听我的心」——她多想用自己的声音，向你证明她的真心。（据歌词）"},{"caption":"他们翻阅她的曾经，字里行间搜寻罪名，自顾自判了死刑，等待血流尽再俯身痛饮。（据歌词）"},{"caption":"可是我不愿向递出刀刃的凶手妥协——只想带着那些无法释怀的曾经，继续前行。（据歌词，PV 字幕）"}]'::jsonb, '[{"label":"投稿B站（BV1VmX5BwE2b）· 《跑！》续作 · 网暴后的心声","date":"2026-03-28"},{"label":"100万播放 · ACE传说曲（用时20日01时38分）","date":"2026-04-17"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;

